PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('admin','vendor','customer')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','banned')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vendors (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,store_name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,logo TEXT,banner TEXT,description TEXT,status TEXT DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),commission_rate REAL DEFAULT 10.00,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT,parent_id INTEGER NULL,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,status TEXT DEFAULT 'active' CHECK(status IN ('active','inactive')),meta_title TEXT,meta_description TEXT);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT,vendor_id INTEGER NOT NULL,category_id INTEGER NOT NULL,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,sku TEXT,price REAL NOT NULL,sale_price REAL DEFAULT 0,stock INTEGER DEFAULT 0,image TEXT,status TEXT DEFAULT 'draft' CHECK(status IN ('draft','active','inactive')),meta_title TEXT,meta_description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vendor_id) REFERENCES vendors(id),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE VIRTUAL TABLE product_search USING fts5(name, description, content='products', content_rowid='id');
CREATE TRIGGER products_ai AFTER INSERT ON products BEGIN INSERT INTO product_search(rowid,name,description) VALUES (new.id,new.name,new.description); END;
CREATE TRIGGER products_ad AFTER DELETE ON products BEGIN INSERT INTO product_search(product_search,rowid,name,description) VALUES('delete',old.id,old.name,old.description); END;
CREATE TRIGGER products_au AFTER UPDATE ON products BEGIN INSERT INTO product_search(product_search,rowid,name,description) VALUES('delete',old.id,old.name,old.description); INSERT INTO product_search(rowid,name,description) VALUES (new.id,new.name,new.description); END;
CREATE TABLE product_attributes (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,name TEXT,value TEXT,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_variants (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,sku TEXT,options_json TEXT,price REAL,stock INTEGER,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_images (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,path TEXT,sort_order INTEGER DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE coupons (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,type TEXT CHECK(type IN ('fixed','percent')),value REAL,starts_at TEXT,ends_at TEXT,status TEXT DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,number TEXT UNIQUE,status TEXT,payment_status TEXT,shipping_status TEXT,payment_method TEXT,total REAL,commission_total REAL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,product_id INTEGER,vendor_id INTEGER,quantity INTEGER,price REAL,total REAL,commission REAL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE refunds (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,amount REAL,reason TEXT,status TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payouts (id INTEGER PRIMARY KEY AUTOINCREMENT,vendor_id INTEGER,amount REAL,status TEXT DEFAULT 'requested' CHECK(status IN ('requested','approved','paid','rejected')),requested_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,user_id INTEGER,rating INTEGER,comment TEXT,status TEXT DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE wishlists (user_id INTEGER,product_id INTEGER,PRIMARY KEY(user_id,product_id));
CREATE TABLE addresses (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,label TEXT,line1 TEXT,city TEXT,state TEXT,postal_code TEXT,country TEXT);
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,type TEXT,message TEXT,read_at TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE api_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,token_hash TEXT,expires_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE activitylogs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT,ip TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
